import { getGlobal } from "@/lib/cms";
import { CmsAdapterProvider } from "@propeller-commerce/propeller-v2-cms-react";
import { PREPR_ENABLED } from "@/lib/preprEvent";
import PreprSegmentsSync from "@/components/cms/PreprSegmentsSync";
import PreprPreviewBar from "@/components/cms/PreprPreviewBar";

// Prepr tracking pixel token. The pixel manages the __prepr_uid visitor cookie;
// per-page content events are fired by <PreprTrack> (View for pages/posts, Tag
// for category interest) so Prepr can attribute engagement to the visitor and
// build behavioral segments. Only mounted when Prepr is the active CMS.
const PREPR_TRACKING_TOKEN = process.env.NEXT_PUBLIC_PREPR_TRACKING_TOKEN;

// Resolved server-side because only the server can reach the channel: the id
// is NEXT_PUBLIC_BASE_CATEGORY_ID when set, else `channel(...).catalogRootId`.
// Seeded to the client so components that fetch the menu themselves (every
// page rendering `<Header />` rather than `<HeaderServer />`) ask for the same
// category the server does, instead of guessing a literal.
const [globalData, cookieStore, baseCategoryId, initialLanguage, anonymousUserId] = await Promise.all([
  getGlobal(),
  cookies(),
  resolveBaseCategoryId(),
  // Same resolver every page uses, so `<html lang>` and the client
  // provider can never disagree with what the page fetched.
  resolveRequestLanguage(),
  // Channel-only value, so the client cannot resolve it: it scopes logged-out
  // listing queries to the channel's anonymous user, matching what the SSR
  // seed already sends.
  resolveAnonymousUserId(),
]);

